import requests
for term in ['Ifitm1 AND Tspo AND Lgmn AND LPS AND mouse', 'Ifitm1 Tspo Lgmn Mafb LPS', 'Ifitm1 AND Tspo AND Lgmn AND Mafb AND dendritic', 'Wfdc17 AND Ms4a6d AND Mcemp1']:
    r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'gds','term':term,'retmax':'10','retmode':'json'})
    ids=r.json()['esearchresult'].get('idlist',[])
    print(term, ids)
    for i in ids[:5]:
        try:
            rr=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'gds','id':i,'retmode':'json'})
            d=rr.json()['result'][i]
            print(' ',d.get('accession'),d.get('title'))
        except Exception as e: print(' err')
PY"

